/// <summary>
/// AVA/WEN/2025/04/07        AVA_012999_EntAsset_Project
/// </summary>
/// <returns>boolean</returns>
public boolean checkEntAssetObjectTable()
{
    boolean ret = true;
    KCS_PTMToolTable    toolTable;

    toolTable = KCS_PTMToolTable::find(this.ObjectID);
    if (!toolTable)
    {
        ret = checkFailed(strFmt("@NDX:NXAToolTableNotExistant", this.ObjectID));
    }
    else
    {
        if (!toolTable.avaICProjMaintenanceExist())
        {
            ret = checkFailed("@NDX:NXANoMaintananceProject");
        }
    }

    return ret;
}
